solution.main.py:
slice_length = int(input())
processes = []
while True:
    try:
        line = input()
    except EOFError:
        break
    parts = line.split()
    if parts:
        processes.append({"name": parts[0], "arrival": int(parts[1]), "burst": int(parts[2]), "left": int(parts[2]), "finish": 0})

waiting = sorted(processes, key=lambda p: p["arrival"])
queue = []
stretches = []
clock = 0

def admit(time):
    while waiting and waiting[0]["arrival"] <= time:
        queue.append(waiting.pop(0))

def record(start, end, name):
    if stretches and stretches[-1][2] == name and stretches[-1][1] == start:
        stretches[-1][1] = end
    else:
        stretches.append([start, end, name])

admit(clock)
while queue or waiting:
    if not queue:
        record(clock, waiting[0]["arrival"], "idle")
        clock = waiting[0]["arrival"]
        admit(clock)
        continue
    process = queue.pop(0)
    run = min(slice_length, process["left"])
    record(clock, clock + run, process["name"])
    clock += run
    process["left"] -= run
    admit(clock)
    if process["left"] > 0:
        queue.append(process)
    else:
        process["finish"] = clock

for start, end, name in stretches:
    print(f"t={start}-{end} {name}")
total = 0
for p in processes:
    wait = p["finish"] - p["arrival"] - p["burst"]
    total += wait
    print(f"{p['name']} finished at {p['finish']}, waited {wait}")
print(f"Average wait: {total / len(processes):.2f}")
